const { runId, idea } = $json.body;
if (typeof runId !== 'string' || typeof idea !== 'string' || !idea.trim() || idea.length > 5000) throw new Error('Invalid request');
return [{ json: { runId, idea, model: 'gpt-4.1-mini', agents: {} } }];

const state = $('Configure model').first().json;
if ($json.status !== 'completed') throw new Error('OpenAI response was incomplete');
const text = ($json.output || []).flatMap(item => item.content || []).filter(item => item.type === 'output_text').map(item => item.text).join('');
const result = JSON.parse(text);
if (typeof result.summary !== 'string' || !Array.isArray(result.details)) throw new Error('Invalid agent result');
return [{ json: { ...state, agents: { ...state.agents, architect: result } } }];

